"""Подробный отчёт варианта 11; расчёты сверяются с реальным запуском Rust.

Запуск из корня: python3 scripts/lab_04_vigenere/detailed_variant_11.py
Нужны python-docx, lxml и доступный cargo с зависимостями workspace.
"""
from __future__ import annotations

from collections import Counter
from pathlib import Path
import subprocess
import sys
import textwrap

ROOT = Path(__file__).resolve().parents[2]
sys.path.insert(0, str(ROOT / 'scripts'))
sys.path.insert(0, str(Path(__file__).resolve().parent))

from docx.oxml import OxmlElement
from docx.shared import Cm, Pt
from docx.enum.text import WD_ALIGN_PARAGRAPH
from math_helpers import ALPHABET33, RU_FREQ, columns, decrypt, index_of_coincidence, key_length_scores, recover_key, to_indices
from report_builder import LabMeta, make_doc, add_title_page, add_page_break, add_heading, add_para, add_listing, add_math, add_qa, save, omml_display, m_text, m_op, m_frac, m_sub, m_sup, m_sum

OUT = ROOT / 'docs/reports/2025/lab_04_vigenere/var_11/Ковалев Д.П. ВКБ43 4 лаба.docx'
ART = ROOT / 'artifacts/lab_04_vigenere/var_11'


def table(doc, title, headers, rows):
    add_para(doc, title, indent=False)
    doc.paragraphs[-1].paragraph_format.keep_with_next = True
    t = doc.add_table(rows=1, cols=len(headers))
    t.style = 'Table Grid'
    t.autofit = False
    for cell in t.rows[0].cells:
        cell.width = Cm(16.5 / len(headers))
    for cell, value in zip(t.rows[0].cells, headers):
        cell.text = str(value)
    header = OxmlElement('w:tblHeader')
    t.rows[0]._tr.get_or_add_trPr().append(header)
    for row in rows:
        for cell, value in zip(t.add_row().cells, row):
            cell.text = str(value)
    for ri, row in enumerate(t.rows):
        row._tr.get_or_add_trPr().append(OxmlElement('w:cantSplit'))
        for cell in row.cells:
            for p in cell.paragraphs:
                p.paragraph_format.first_line_indent = Cm(0)
                p.paragraph_format.line_spacing = 1
                p.paragraph_format.space_after = Pt(3)
                for run in p.runs:
                    run.font.name = 'Times New Roman'
                    run.font.size = Pt(11)
                    run.bold = ri == 0
    doc.add_paragraph()


def formula(doc, text):
    add_math(doc, omml_display([m_text(text, italic=False)]))


def chi_scores(counts, n):
    return [sum((counts[(i+s) % 33] - RU_FREQ[a]*n)**2 / (RU_FREQ[a]*n)
                for i, a in enumerate(ALPHABET33)) for s in range(33)]


def build_report():
    cipher = (ROOT / 'artifacts/lab_04_vigenere/cipher_texts/var_11.txt').read_text().strip()
    if any(c not in ALPHABET33 for c in cipher):
        raise ValueError('Шифртекст содержит символ вне алфавита')
    idx = to_indices(cipher)
    scores = key_length_scores(idx, 2, 8)
    key, shifts = recover_key(idx, 4)
    plain = decrypt(idx, key)
    cols = columns(idx, 4)
    counts = [[Counter(col)[i] for i in range(33)] for col in cols]
    chis = [chi_scores(c, len(col)) for c, col in zip(counts, cols)]
    if key != 'ДВОР' or len(cipher) != 2620:
        raise ValueError('Исходные данные варианта изменились')
    run = subprocess.run(['cargo', 'run', '--quiet', '-p', 'vigenere', '--',
                          'break', cipher, '--scheme', 'standard', '--alphabet', 'ru-no-yo',
                          '--min-key', '2', '--max-key', '8'],
                         cwd=ROOT, capture_output=True, text=True, check=True)
    if f'Восстановленный ключ: {key}' not in run.stdout or f'Расшифрованный текст: {plain}' not in run.stdout:
        raise ValueError('Результаты Python и Rust различаются')
    enc = subprocess.run(['cargo', 'run', '--quiet', '-p', 'vigenere', '--',
                          'encrypt', '--scheme', 'standard', '--alphabet', 'ru-no-yo',
                          '--text', plain, '--key', key], cwd=ROOT,
                         capture_output=True, text=True, check=True)
    if enc.stdout.strip() != cipher:
        raise ValueError('Обратное шифрование Rust не совпало с исходными данными')
    ART.mkdir(parents=True, exist_ok=True)
    (ART / 'run.txt').write_text(run.stdout)
    (ART / 'plaintext.txt').write_text(plain + '\n')

    doc = make_doc()
    doc.sections[0].page_width = Cm(21)
    doc.sections[0].page_height = Cm(29.7)
    add_title_page(doc, LabMeta(4, 'Изучение математических моделей шифра Виженера и численных методов его реализации', 11))
    add_page_break(doc)
    add_heading(doc, '1. Цель работы и задание')
    add_para(doc, 'Цель работы: изучить шифрование и дешифрование шифром Виженера, понять его математическую модель и освоить восстановление неизвестного ключа по статистике шифртекста.')
    add_para(doc, 'Задание варианта №11: расшифровать текст из таблицы 2.9 методических указаний. Ключ заранее неизвестен. Необходимо определить его длину, найти буквы ключа, показать таблицы и примеры вычислений, привести исходный и расшифрованный тексты и сделать выводы.')
    add_para(doc, 'Источник: docs/conditions/Лабораторная 4.pdf, вариант 11 на печатных страницах 70–72. Файл исходных данных: artifacts/lab_04_vigenere/cipher_texts/var_11.txt. Все 2620 символов этого файла сверены с текстом варианта в PDF. Полный шифртекст приведён в приложении А.')
    add_para(doc, 'Порядок решения: согласовать алфавит → проверить возможные длины ключа → разделить текст на столбцы → определить сдвиг каждого столбца → расшифровать → проверить результат обратным шифрованием. Сначала рассмотрим смысл операций, затем выполним их на данных варианта.')

    add_heading(doc, '2. Как работает шифр Виженера')
    add_heading(doc, '2.1. Алфавит и нумерация символов', level=2)
    add_para(doc, 'Используются 32 русские буквы без отдельной Ё и знак «_», обозначающий пробел. Всего 33 символа. Е и Ё считаются одной буквой; Ъ и Ь в шифровании обязательно сохраняются разными. Удаление Ъ изменило бы номера последующих символов и результат всех операций по модулю 33.')
    table(doc, 'Таблица 1 — номера символов (нумерация с нуля)', ['Номер', 'Символ', 'Номер', 'Символ', 'Номер', 'Символ'],
          [[i, ALPHABET33[i], i+11, ALPHABET33[i+11], i+22, ALPHABET33[i+22]] for i in range(11)])
    add_para(doc, 'Переносы строк и отступы в PDF — оформление, их удаляют при переносе шифртекста. Подчёркивания удалять нельзя: это полноценные зашифрованные символы. Обычный пробел CLI не принимает; открытый текст для запуска также записывается с «_». В таблицах ниже позиции текста считаются с 1, а номера букв алфавита — с 0.')
    add_heading(doc, '2.2. Формулы и таблица Виженера', level=2)
    add_para(doc, 'Одна буква ключа задаёт сдвиг Цезаря. Виженер чередует такие сдвиги и повторяет ключ до конца сообщения. Обозначим номер открытой буквы через p, зашифрованной — через c, длину ключа — через L. Для позиции i, считая с нуля:')
    add_math(doc, omml_display([m_sub(m_text('c'),m_text('i')),m_op(' = ('),m_sub(m_text('p'),m_text('i')),m_op(' + '),m_sub(m_text('k'),m_text('i mod L')),m_op(') mod 33')]))
    add_math(doc, omml_display([m_sub(m_text('p'),m_text('i')),m_op(' = ('),m_sub(m_text('c'),m_text('i')),m_op(' − '),m_sub(m_text('k'),m_text('i mod L')),m_op(' + 33) mod 33')]))
    add_para(doc, 'Операция mod 33 возвращает остаток от деления на 33, то есть номер от 0 до 32. После последнего символа алфавита снова идёт А. При расшифровке прибавление 33 позволяет избежать отрицательного числа. Выражение i mod L выбирает нужную букву циклически повторяющегося ключа.')
    table(doc, 'Таблица 2 — фрагмент матрицы Виженера', ['Ключ / текст']+ALPHABET33[:8], [[ALPHABET33[k]]+[ALPHABET33[(k+p)%33] for p in range(8)] for k in range(8)])
    add_para(doc, 'Полная матрица имеет размер 33×33. В нулевой строке стоит алфавит; каждая следующая строка сдвинута влево на один символ. При шифровании выбираем строку по букве ключа, столбец по открытой букве, на пересечении читаем шифрбукву. При расшифровке находим шифрбукву в строке ключа и читаем заголовок её столбца.')
    add_heading(doc, '2.3. Проверка на примере из методички', level=2)
    ep='ПРИВЕТ_МИР'; ek='НОТА'
    rows=[]; example=''
    for i,p in enumerate(ep):
        k=ek[i%4]; a=ALPHABET33.index(p); b=ALPHABET33.index(k); c=(a+b)%33; example+=ALPHABET33[c]
        rows.append([i+1, f'{p} ({a})', f'{k} ({b})', f'{a}+{b} mod 33 = {c}', ALPHABET33[c]])
    table(doc, 'Таблица 3 — шифрование «ПРИВЕТ_МИР» ключом «НОТА»', ['Позиция', 'Текст (номер)', 'Ключ (номер)', 'Вычисление', 'Результат'], rows)
    add_para(doc, f'Получено «{example}», как в методичке. Например, П имеет номер 15, Н — 13: 15 + 13 = 28, а номеру 28 соответствует Ь. Для пробела: (32 + 18) mod 33 = 17, то есть С. Ключ продвигается и на позиции пробела.')
    formula(doc, '(28 − 13 + 33) mod 33 = 15 → П')

    add_heading(doc, '3. Шаг 1. Определение длины ключа')
    add_para(doc, 'Если длина ключа равна L, символы на позициях 1, 1+L, 1+2L и далее зашифрованы первой буквой ключа. Позиции 2, 2+L, 2+2L — второй буквой. Поэтому при верном L каждый столбец представляет собой отдельный шифр Цезаря. Сдвиг меняет названия букв, но сохраняет числа их повторений.')
    add_para(doc, 'Индекс совпадения IC — вероятность того, что два разных случайно выбранных места столбца содержат одинаковый символ. Пусть N — число символов столбца, а nᵣ — число вхождений символа с номером r. Для каждой буквы существует nᵣ(nᵣ−1) упорядоченных пар совпадающих позиций, а всего разных упорядоченных пар N(N−1):')
    add_math(doc, omml_display([m_text('IC'),m_op(' = '),m_frac(m_sum(m_text('r=0'),m_text('32'),m_sub(m_text('n'),m_text('r'))+m_op('(')+m_sub(m_text('n'),m_text('r'))+m_op('−1)')),m_text('N(N−1)'))]))
    add_para(doc, 'У равновероятных независимых символов IC около 1/33 = 0,0303. Русский текст неравномерен: пробелы, О и Е встречаются чаще редких букв, поэтому IC обычно выше. Методичка использует ориентир 0,053–0,07. Это не точная константа: значение зависит от текста и учёта пробелов. На практике сравниваем несколько длин и ищем выраженный подъём.')
    add_para(doc, 'Перебираем длины от 2 до 8. Это выбранный диапазон поиска, совпадающий с командой запуска ниже, а не известная заранее длина. Для каждой длины отдельно строим столбцы, считаем IC каждого и берём их среднее арифметическое.')
    formula(doc, 'ICср(L) = (IC₁ + IC₂ + … + ICₗ) / L')
    mx=max(v for _,v in scores); cutoff=0.95*mx
    table(doc, 'Таблица 4 — сравнение предполагаемых длин', ['L', 'Длины столбцов', 'Средний IC', 'Не ниже 95% максимума'],
          [[l, str(len(idx)//l) if len(idx)%l==0 else f'{len(idx)//l}–{len(idx)//l+1}', f'{v:.8f}', 'да' if v>=cutoff else 'нет'] for l,v in scores])
    add_para(doc, f'Максимум равен {mx:.8f}. Реализация выбирает наименьшую длину, для которой средний IC составляет хотя бы 95% максимума. Порог: {cutoff:.8f}. Ему удовлетворяют 4 и 8; выбираем 4. Это практическая эвристика программы, а не универсальная теорема о любом шифртексте.')
    add_para(doc, 'Почему не 8? Период 4 укладывается в 8, и столбцы всё равно содержат символы одного сдвига, поэтому IC почти такой же. Почему не 2? В каждом столбце смешиваются два разных сдвига: Д с О и В с Р, поэтому IC ниже. Близость только к числу 0,0553 дала бы здесь неверное обоснование: важны общая картина пиков и проверка расшифровки.')
    add_heading(doc, '3.1. Как вручную разложить текст на четыре столбца', level=2)
    table(doc, 'Таблица 5 — первые восемь строк разбиения', ['Позиции', 'Столбец 1', 'Столбец 2', 'Столбец 3', 'Столбец 4'], [[f'{4*r+1}–{4*r+4}']+list(cipher[4*r:4*r+4]) for r in range(8)])
    add_para(doc, 'Текст записывается слева направо по четыре символа в строке. Затем читаем вертикально. Первый столбец начинается «ЖПГФДМДХ…», второй — «ВКЗРБПББ…». В каждом столбце 2620 / 4 = 655 символов. Не нужно делить текст на четыре последовательных куска по 655 символов: это другое разбиение.')
    table(doc, 'Таблица 6 — абсолютные частоты всех символов', ['Символ', 'Столбец 1', 'Столбец 2', 'Столбец 3', 'Столбец 4'], [[a]+[cnt[i] for cnt in counts] for i,a in enumerate(ALPHABET33)]+[['Итого']+[sum(c) for c in counts]])
    add_heading(doc, '3.2. Численный расчёт IC', level=2)
    nums=[sum(n*(n-1) for n in cnt) for cnt in counts]
    add_para(doc, 'Для первого столбца берём числа из таблицы 6: А встречается 1 раз, Б — 8, В — 10, Г — 117 и т. д. Например, вклад Г в числитель: 117·116 = 13572. Буквы с частотой 0 или 1 дают нулевой вклад. Складываем такие вклады для всех 33 символов.')
    formula(doc, 'S₁ = 1·0 + 8·7 + 10·9 + 117·116 + … + 14·13 + 14·13')
    add_math(doc,omml_display([m_text('IC₁ = '),m_frac(m_text(str(nums[0])),m_text('655·654')),m_op(f' = {index_of_coincidence(cols[0]):.8f}')]))
    table(doc, 'Таблица 7 — IC каждого столбца при L = 4', ['Столбец', 'N', 'Σ nᵣ(nᵣ−1)', 'N(N−1)', 'IC'], [[j+1,655,nums[j],655*654,f'{index_of_coincidence(cols[j]):.8f}'] for j in range(4)])
    formula(doc, 'ICср(4) = ('+' + '.join(f'{index_of_coincidence(c):.6f}' for c in cols)+') / 4')
    formula(doc, f'ICср(4) ≈ {dict(scores)[4]:.8f} → L = 4')

    add_heading(doc, '4. Шаг 2. Нахождение букв ключа')
    add_heading(doc, '4.1. Взаимный индекс совпадения: способ из методички', level=2)
    add_para(doc, 'Обычный IC сравнивает буквы внутри одного столбца. Взаимный индекс MIC сравнивает два разных столбца. Чтобы найти разность их сдвигов, сравним каждый из столбцов 2–4 с первым. Для пробного d вычитаем d из номеров букв сравниваемого столбца по модулю 33. Тогда его частота в позиции r равна исходной частоте в позиции (r+d) mod 33.')
    add_math(doc, omml_display([m_text('MIC₁ⱼ(d) = '),m_frac(m_sum(m_text('r=0'),m_text('32'),m_text('n₁,r · nⱼ,(r+d) mod 33')),m_text('N₁ · Nⱼ'))]))
    add_para(doc, 'Перебираем d от 0 до 32 и выбираем максимум MIC. Когда сдвиги выровнены, часто встречающиеся буквы в двух столбцах оказываются на одинаковых местах. Используем именно определённое выше направление сдвига: d соответствует разности «ключ столбца j минус ключ первого столбца».')
    microws=[]; deltas=[0]
    for j in range(1,4):
        vals=[sum(counts[0][i]*counts[j][(i+d)%33] for i in range(33))/655**2 for d in range(33)]
        d=max(range(33),key=vals.__getitem__); deltas.append(d)
        microws.append([f'1 и {j+1}', f'{vals[0]:.8f}', d, f'{vals[d]:.8f}'])
    table(doc, 'Таблица 8 — относительные сдвиги по максимуму MIC', ['Столбцы', 'MIC без сдвига', 'Лучший d', 'Максимальный MIC'], microws)
    add_para(doc, 'Получены относительные сдвиги 0, 31, 10, 12. Число 31 равносильно −2 по модулю 33. MIC определяет разности букв ключа, но не первую букву: остаётся 33 возможных общих сдвига. Если номер первой буквы t, весь ключ определяется так:')
    formula(doc, 'k = (t, (t+31) mod 33, (t+10) mod 33, (t+12) mod 33)')
    table(doc, 'Таблица 9 — соседние кандидаты общего сдвига', ['t', 'Ключ', 'Начало расшифровки'], [[t, ''.join(ALPHABET33[(t+d)%33] for d in deltas), decrypt(idx,''.join(ALPHABET33[(t+d)%33] for d in deltas))[:24]] for t in [3,4,5]])
    add_para(doc, 'При t = 4 получаем (4, 2, 14, 16), то есть «ДВОР», и начало «ВАСИЛИСА_ЕГОРОВНА_ПРИНЯЛА». Общий сдвиг можно выбрать по читаемости кандидатов, как в методическом подходе, или по сравнению частот с русским языком. Ниже показан численный способ, используемый в Rust.')
    add_heading(doc, '4.2. Критерий χ²: способ программной реализации', level=2)
    add_para(doc, 'В каждом столбце независимо перебираем 33 возможных ключевых сдвига s. Для каждого варианта мысленно расшифровываем столбец и сравниваем полученные количества букв с ожидаемыми для русского текста. Чем меньше расхождение, тем лучше кандидат.')
    formula(doc, 'Oᵣ(s) = n(r+s) mod 33;     Eᵣ = N · fᵣ')
    add_math(doc,omml_display([m_sup(m_text('χ'),m_text('2')),m_text('(s) = '),m_sum(m_text('r=0'),m_text('32'),m_frac(m_sup(m_text('(Oᵣ(s) − Eᵣ)'),m_text('2')),m_text('Eᵣ')))]))
    add_para(doc, 'Здесь fᵣ — эталонная доля буквы; Eᵣ — ожидаемое число её появлений в 655 символах; Oᵣ(s) — фактическое число после пробного сдвига. Квадрат делает все отклонения положительными. Деление на Eᵣ учитывает, что избыток редкой буквы существеннее такого же избытка распространённой. Здесь χ² служит для ранжирования сдвигов; статистическая проверка гипотез по p-value не выполняется.')
    table(doc, 'Таблица 10 — частоты, используемые программой (shared/src/alphabet.rs)', ['Буква', 'f', 'Буква', 'f', 'Буква', 'f'], [[ALPHABET33[i], f'{RU_FREQ[ALPHABET33[i]]:.3f}',ALPHABET33[i+11], f'{RU_FREQ[ALPHABET33[i+11]]:.3f}',ALPHABET33[i+22], f'{RU_FREQ[ALPHABET33[i+22]]:.3f}'] for i in range(11)])
    add_para(doc, 'В существующей таблице программы сумма частот равна 1,015; для Ъ и Ь записано по 0,014. Это приближённая модель, а не точно нормированное распределение. Для воспроизводимости расчёты здесь используют эти же значения. Нормирование всей таблицы общим множителем изменило бы числа χ², но не порядок сдвигов: сумма наблюдений одинакова для всех кандидатов.')
    add_para(doc, 'Рассмотрим первый столбец и сдвиг s = 4 (Д). После вычитания 4 буква Д шифртекста становится А, Т становится О, Г становится пробелом. Поэтому количества А, О и пробелов после расшифровки нужно брать из строк Д, Т и Г таблицы 6.')
    detail=[]
    for a in ['А','О','_','Ъ']:
        i=ALPHABET33.index(a); source=(i+4)%33; obs=counts[0][source]; expected=655*RU_FREQ[a]
        detail.append([a,ALPHABET33[source],obs,f'{expected:.3f}',f'{(obs-expected)**2/expected:.5f}'])
    table(doc, 'Таблица 11 — отдельные слагаемые χ² для первого столбца, s = 4', ['Открытая буква', 'Шифрбуква', 'O', 'E = 655·f', '(O−E)²/E'],detail)
    formula(doc, 'EА = 655 · 0,062 = 40,61;     OА(4) = 63')
    add_math(doc,omml_display([m_text('Вклад А = '),m_frac(m_sup(m_text('(63 − 40,61)'),m_text('2')),m_text('40,61')),m_text(f' ≈ {(63-40.61)**2/40.61:.5f}')]))
    add_para(doc, 'Аналогично вычисляются остальные 32 слагаемых. Сумма по всем буквам для s = 4 равна 72,97445. Это не сумма только четырёх строк таблицы 11: они приведены как подробные примеры.')
    table(doc, 'Таблица 12 — все проверенные сдвиги', ['s', 'Буква', 'χ², ст. 1', 'χ², ст. 2', 'χ², ст. 3', 'χ², ст. 4'], [[s,ALPHABET33[s]]+[f'{v[s]:.2f}' for v in chis] for s in range(33)])
    table(doc, 'Таблица 13 — выбранные буквы ключа', ['Столбец', 'Лучший s', 'Буква', 'Минимум χ²', 'Следующий кандидат: буква / χ²'], [[j+1,s,ALPHABET33[s],f'{chi:.5f}', f'{ALPHABET33[sorted(range(33),key=chis[j].__getitem__)[1]]} / {sorted(chis[j])[1]:.2f}'] for j,(_,s,chi) in enumerate(shifts)])
    add_para(doc, 'Читаем буквы в порядке столбцов: Д, В, О, Р. Ключ — «ДВОР», числовой ключ — (4, 2, 14, 16). Таким образом, независимый подбор по χ² совпал с относительными сдвигами по MIC. Всего при известной длине требуется 4·33 = 132 оценки сдвига вместо перебора всех 33⁴ = 1 185 921 четырёхбуквенных ключей.')

    add_heading(doc, '5. Шаг 3. Расшифровка и проверка')
    add_para(doc, 'Повторяем ДВОР под всем шифртекстом. Из номера каждой шифрбуквы вычитаем номер соответствующей буквы ключа по модулю 33. Нельзя искать отдельный ключ для каждого слова: до расшифровки границы слов неизвестны, и повторение ключа идёт непрерывно.')
    table(doc, 'Таблица 14 — первые 16 символов расшифровки', ['Позиция', 'Шифрбуква (c)', 'Ключ (k)', '(c−k+33) mod 33', 'Текст'], [[i+1,f'{cipher[i]} ({idx[i]})',f'{key[i%4]} ({to_indices(key)[i%4]})', f'({idx[i]}−{to_indices(key)[i%4]}+33) mod 33 = {ALPHABET33.index(plain[i])}',plain[i]] for i in range(16)])
    add_para(doc, 'Например, первая буква Ж имеет номер 6: (6−4+33) mod 33 = 2 → В. Девятая буква Г имеет номер 3: (3−4+33) mod 33 = 32 → пробел. Получается «ВАСИЛИСА_ЕГОРОВНА…». Полный результат дан в приложении Б без пропусков.')
    add_para(doc, 'Проверка состоит из двух частей. Смысловая: весь результат представляет связный русский текст. Техническая: шифруем полученные 2620 символов ключом «ДВОР» и посимвольно сравниваем с исходным файлом. Реальный запуск Rust дал полное совпадение, несовпадающих позиций — 0.')
    add_para(doc, 'Обратное шифрование подтверждает корректность операций и отсутствие потерь данных, но само по себе не доказывает правильность ключа: любой ключ обратим. Выбор «ДВОР» подтверждается совокупностью IC, MIC, минимальных χ² и осмысленности всей расшифровки.')

    add_heading(doc, '6. Как запустить и где это реализовано')
