    add_listing(doc, 'cipher=$(tr -d \'\\r\\n\' < artifacts/lab_04_vigenere/cipher_texts/var_11.txt)\ncargo run --quiet -p vigenere -- \\\n  break "$cipher" --scheme standard --alphabet ru-no-yo --min-key 2 --max-key 8')
