    add_para(doc, 'Для расшифровки уже известным ключом и проверки учебного примера:')
    add_listing(doc, 'cargo run --quiet -p vigenere -- \\\n  decrypt --scheme standard --alphabet ru-no-yo --text "$cipher" --key ДВОР\ncargo run --quiet -p vigenere -- \\\n  encrypt --scheme standard --alphabet ru-no-yo --text ПРИВЕТ_МИР --key НОТА')
    add_para(doc, 'Для повторения обратной проверки используйте сохранённую расшифровку:')
